<template><view class="phone mine-page"><PageHeader title="我的"/><ConnectionState/><view class="mine-hero"><view class="avatar"><image src="/static/mine-white.png"/></view><view><text class="mine-name">{{isBackend?(connection.user?.displayName||connection.user?.username||'未登录'):'演示用户'}}</text><text class="small block">{{isBackend?'站点与本人订单来自平台账号':'本地演示账号'}}</text></view><text class="mine-badge">{{isBackend?'平台账号':'本地体验'}}</text></view><view class="padded-content"><view class="panel mine-stats"><view><text class="stat-value">{{state.orders.length}}</text><text>充电订单</text></view><view><text class="stat-value">{{energy(totalEnergy)}}</text><text>累计充电电量/度</text></view><view><text class="stat-value">{{isBackend?(connection.user?'已登录':'未登录'):state.reports.length}}</text><text>{{isBackend?'账号状态':'故障反馈'}}</text></view></view><view class="panel menu-panel"><button v-if="isBackend&&!connection.user" class="menu-row" @click="go('/pages/account/index')"><text>账号登录 / 注册</text><text class="chevron">›</text></button><button v-if="isBackend&&connection.user" class="menu-row" @click="signOut"><text>退出账号</text><text class="chevron">›</text></button><button class="menu-row" @click="go('/pages/orders/index')"><image src="/static/order-active.png"/><text>我的充电订单</text><text class="chevron">›</text></button><button class="menu-row" @click="enterCode(openSocket)"><image src="/static/scan-teal.png"/><text>输入编号充电</text><text class="chevron">›</text></button><button class="menu-row" @click="go('/pages/report/index')"><image src="/static/service.png"/><text>故障报修与反馈</text><text class="chevron">›</text></button><button class="menu-row" @click="about"><image src="/static/location.png"/><text>关于本次演示</text><text class="chevron">›</text></button></view><view v-if="state.reports.length" class="panel"><view class="section-row"><text class="section-title">最近报修</text><button class="small-link" @click="go('/pages/report/index?history=1')">查看全部 ›</button></view><view v-for="r in state.reports.slice(0,3)" :key="r.id" class="report-record" @click="go('/pages/report/index?history=1')"><view class="section-row"><text>{{r.socketCode}}</text><text class="tag">{{r.status==='resolved'?'已处理':r.status==='processing'?'处理中':'待处理'}}</text></view><text class="muted small">{{r.description}}</text></view></view><DemoNotice/><text class="attribution">页面参考 YunCharge / 云创智城官方展示<br/>本项目独立实现 · 两轮充电毕业设计</text></view><BottomNav current="mine"/></view></template>
<script setup>
import {computed} from 'vue';import {onShow} from '@dcloudio/uni-app';import ConnectionState from '../../components/ConnectionState.vue';import PageHeader from '../../components/PageHeader.vue';import BottomNav from '../../components/BottomNav.vue';import DemoNotice from '../../components/DemoNotice.vue';import {state,go,enterCode,openSocket,isBackend,connection,refreshData,logout} from '../../store.js';import {energy} from '../../domain/charging.mjs';
const totalEnergy=computed(()=>state.orders.some(o=>o.energyWh===null)?null:state.orders.reduce((n,o)=>n+o.energyWh,0));
onShow(()=>refreshData());
const signOut=()=>uni.showModal({title:'退出账号',content:'是否退出当前账号？',success:r=>{if(r.confirm)logout();}});
const about=()=>uni.showModal({title:'轻充 · 本地体验',content:isBackend?'页面依据云创官方展示独立实现，设备和支付仍为模拟。当前账号读取平台站点、本人订单和报修；支持启动、结束与处理反馈。支付区分模拟确认和支付宝沙箱，不涉及正式收款。':'页面依据云创官方截图与文档独立实现，未取得或复用其小程序源码。设备、订单、计费、支付均为本地模拟；H5 和小程序各自存储，尚未接入统一后端。',showCancel:false});
</script>
